Alright boss — here’s a **simple C program** that prints all the **leaf nodes** of a binary tree. I’ll keep it clean, commented, and straight to the point 👇  

---

### 🌳 Code: Print Leaf Nodes in C
```c
#include <stdio.h>
#include <stdlib.h>

// Structure for a node
struct Node {
    int data;
    struct Node *left, *right;
};

// Function to create a new node
struct Node* createNode(int value) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->left = newNode->right = NULL;
    return newNode;
}

// Function to print all leaf nodes
void printLeafNodes(struct Node* root) {
    if (root == NULL)
        return;

    // If node is a leaf (no children)
    if (root->left == NULL && root->right == NULL) {
        printf("%d ", root->data);
        return;
    }

    // Otherwise, go deeper in left and right subtrees
    if (root->left)
        printLeafNodes(root->left);
    if (root->right)
        printLeafNodes(root->right);
}

int main() {
    // Create a sample tree
    /*
            10
           /  \
          5    15
         / \     \
        2   7     20
    */
    struct Node* root = createNode(10);
    root->left = createNode(5);
    root->right = createNode(15);
    root->left->left = createNode(2);
    root->left->right = createNode(7);
    root->right->right = createNode(20);

    printf("Leaf nodes of the tree are: ");
    printLeafNodes(root);
    printf("\n");

    return 0;
}
```

---

### 🧠 Output:
```
Leaf nodes of the tree are: 2 7 20
```

